/**
 * Google reviews for Prim Ahuja's business (Queensland Fundings on Google Maps), captured from the listing
 * on 2026-09-29: 107 reviews, 5.0 average, 106 of them five stars. Each review's text is exactly as
 * written on Google; only surrounding whitespace and a leading row of star emojis were tidied. Newest first.
 * A review left without a comment keeps an empty `text`: it is counted but never listed. `avatar` is the
 * reviewer's own Google profile photo (public/images/reviewers), only where they uploaded one; the rest get
 * a monogram, as on Google.
 *
 * FEATURED (below) is the homepage carousel, in order. `quote` is a verbatim excerpt for the places that
 * fit one or two sentences; the reviews page always shows the full text.
 *
 * To refresh: export the reviews from Google again, update GOOGLE.count / fiveStar / fetched, and replace
 * the REVIEWS list, keeping the ids of any review a page names (see pick() calls and lib/data.ts).
 */
export type ReviewTag = 'first-home' | 'refinance' | 'investment' | 'construction' | 'business';
export type Review = { id: string; name: string; date: string; rating: number; tags: ReviewTag[]; avatar?: string; quote?: string; text: string };

