export const byId = (id: string) => REVIEWS.find((r) => r.id === id);
/** Reviews by id, in the order given; unknown ids are skipped. */
export const pick = (ids: string[]) => ids.map(byId).filter((r): r is Review => !!r);

export const FEATURED: Review[] = pick(['anumeha-jain', 'king-cabamongan', 'nav-k', 'ashish-shukla', 'ruchika-mittal', 'shoji-m']);

/** Count of reviews at each star rating, five first. */
export const DISTRIBUTION = [5, 4, 3, 2, 1].map((stars) => ({ stars, n: REVIEWS.filter((r) => r.rating === stars).length }));

/** "AJ" for "Anumeha Jain", a single letter for a one-word name. */
export function initials(name: string) {
  const words = name.trim().split(/\s+/).filter((w) => /[a-z0-9]/i.test(w));
  if (!words.length) return '·';
  const first = words[0].replace(/[^a-z0-9]/gi, '')[0] ?? '';
  const last = words.length > 1 ? words[words.length - 1].replace(/[^a-z0-9]/gi, '')[0] ?? '' : '';
  return (first + last).toUpperCase();
}

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
/** "Apr 2026" from "2026-04-22". */
export function monthYear(date: string) {
  const [y, m] = date.split('-');
  return `${MONTHS[Number(m) - 1] ?? ''} ${y}`;
}
